'use client';

import { Bell, Search, Moon, Sun, Menu } from 'lucide-react';
import { useState } from 'react';

export default function Header() {
    const [notifications] = useState(3);

    return (
        <header className="sticky top-0 z-30 flex h-16 items-center justify-between border-b border-white/5 bg-[hsl(var(--background))]/80 backdrop-blur-xl px-6">
            {/* Left: Search */}
            <div className="flex items-center gap-4">
                <button className="lg:hidden p-2 rounded-lg hover:bg-white/5">
                    <Menu className="h-5 w-5 text-gray-400" />
                </button>

                <div className="relative hidden md:block">
                    <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-500" />
                    <input
                        type="text"
                        placeholder="Search tenants, licenses..."
                        className="h-10 w-80 rounded-lg bg-white/5 pl-10 pr-4 text-sm text-white placeholder-gray-500 border border-white/10 focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-all"
                    />
                    <kbd className="absolute right-3 top-1/2 -translate-y-1/2 hidden lg:inline-flex h-5 items-center gap-1 rounded border border-white/10 bg-white/5 px-1.5 text-[10px] font-medium text-gray-400">
                        ⌘K
                    </kbd>
                </div>
            </div>

            {/* Right: Actions */}
            <div className="flex items-center gap-3">
                {/* Notifications */}
                <button className="relative p-2 rounded-lg hover:bg-white/5 transition-colors">
                    <Bell className="h-5 w-5 text-gray-400" />
                    {notifications > 0 && (
                        <span className="absolute -top-0.5 -right-0.5 flex h-5 w-5 items-center justify-center rounded-full bg-red-500 text-[10px] font-bold text-white animate-pulse">
                            {notifications}
                        </span>
                    )}
                </button>

                {/* Theme Toggle */}
                <button className="p-2 rounded-lg hover:bg-white/5 transition-colors">
                    <Moon className="h-5 w-5 text-gray-400" />
                </button>

                {/* Status Indicator */}
                <div className="hidden md:flex items-center gap-2 px-3 py-1.5 rounded-full bg-emerald-500/10 border border-emerald-500/20">
                    <span className="h-2 w-2 rounded-full bg-emerald-500 animate-pulse" />
                    <span className="text-xs font-medium text-emerald-400">System Healthy</span>
                </div>
            </div>
        </header>
    );
}
