'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import {
    LayoutDashboard,
    Building2,
    Key,
    CreditCard,
    BarChart3,
    FileText,
    Users,
    ClipboardList,
    Settings,
    Bell,
    ChevronDown,
    LogOut,
} from 'lucide-react';

const navigation = [
    { name: 'Dashboard', href: '/dashboard', icon: LayoutDashboard },
    { name: 'Tenants', href: '/dashboard/tenants', icon: Building2 },
    { name: 'Licenses', href: '/dashboard/licenses', icon: Key },
    { name: 'Plans', href: '/dashboard/plans', icon: CreditCard },
    { name: 'Billing', href: '/dashboard/billing', icon: FileText },
    { name: 'Analytics', href: '/dashboard/analytics', icon: BarChart3 },
    { name: 'Reports', href: '/dashboard/reports', icon: ClipboardList },
    { name: 'Users', href: '/dashboard/users', icon: Users },
    { name: 'Audit Logs', href: '/dashboard/audit', icon: FileText },
    { name: 'Settings', href: '/dashboard/settings', icon: Settings },
];

export default function Sidebar() {
    const pathname = usePathname();

    return (
        <aside className="fixed left-0 top-0 z-40 h-screen w-64 bg-[hsl(var(--sidebar-bg))] border-r border-white/5">
            {/* Logo */}
            <div className="flex h-16 items-center gap-3 px-6 border-b border-white/5">
                <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-indigo-500 to-purple-600 shadow-lg shadow-indigo-500/30">
                    <span className="text-xl font-bold text-white">A</span>
                </div>
                <div>
                    <h1 className="text-lg font-bold text-white">Apex HQ</h1>
                    <p className="text-xs text-gray-400">Super Admin</p>
                </div>
            </div>

            {/* Navigation */}
            <nav className="flex flex-col gap-1 p-4 overflow-y-auto h-[calc(100vh-8rem)]">
                {navigation.map((item) => {
                    const isActive = pathname === item.href || pathname.startsWith(item.href + '/');
                    return (
                        <Link
                            key={item.name}
                            href={item.href}
                            className={`
                flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-all duration-200
                ${isActive
                                    ? 'bg-gradient-to-r from-indigo-500/20 to-purple-500/20 text-white border-l-2 border-indigo-500'
                                    : 'text-gray-400 hover:bg-white/5 hover:text-white'
                                }
              `}
                        >
                            <item.icon className={`h-5 w-5 ${isActive ? 'text-indigo-400' : ''}`} />
                            {item.name}
                        </Link>
                    );
                })}
            </nav>

            {/* User Menu */}
            <div className="absolute bottom-0 left-0 right-0 p-4 border-t border-white/5">
                <div className="flex items-center gap-3 rounded-lg px-3 py-2 hover:bg-white/5 cursor-pointer transition-colors">
                    <div className="h-9 w-9 rounded-full bg-gradient-to-br from-emerald-400 to-cyan-500 flex items-center justify-center">
                        <span className="text-sm font-bold text-white">SA</span>
                    </div>
                    <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-white truncate">Super Admin</p>
                        <p className="text-xs text-gray-400 truncate">admin@apex.com</p>
                    </div>
                    <ChevronDown className="h-4 w-4 text-gray-400" />
                </div>
            </div>
        </aside>
    );
}
